"""Seal the retained failed-phase DATA audit only; no owner/tool invocation."""
from pathlib import Path
import ast,hashlib,json
HERE=Path(__file__).resolve().parent;S=HERE.parent
def load(p):return json.loads(Path(p).read_bytes())
def row(p):
    p=Path(p);b=p.read_bytes();return dict(path=str(p),sha256=hashlib.sha256(b).hexdigest(),bytes=len(b))
def put(n,v):(HERE/n).write_text(json.dumps(v,indent=2)+'\n')
assert not(HERE/'index.json').exists()
audit=load(HERE/'data-audit.json');report=load(audit['rootObservation']['path']);a=audit['artifacts']
assert audit['phasePassed']is audit['metadataDecoded']is audit['adapterAccepted']is False
for d in [audit['rootObservation'],*a.values(),audit['workerResult'],audit['parentObservation'],audit['workerTerminal'],*audit['commandTerminals'].values()]:assert row(d['path'])==d
core=load(HERE/'core-analysis.json');assert core['convertedUnreachableStubs']==14 and len(core['retainedClocks'])==6 and len(core['retainedPoll'])==2
result=dict(schemaVersion=1,state='INDEPENDENT_CLOCK_IO_VALID_ADAPTER_METADATA_FAILURE_REVIEW_PASSED_V1',verifiedPassed=True,sourceIndexSha256=audit['sourceIndex']['sha256'],rootObservation=audit['rootObservation'],sourceIndex=audit['sourceIndex'],sourcePeer=audit['sourcePeer'],rootAuthority=audit['rootAuthority'],rootConfig=audit['rootConfig'],normalizedAdapter=a['normalized-adapter.wasm'],prunedAdapter=a['pruned-adapter.wasm'],metadataPayload=a['embedded-wit-component.wasm'],coreValidation=a['core-validation.json'],structuralAudit=a['structural-audit.json'],metadataTerminal=audit['commandTerminals']['metadata-wit'],workerResult=audit['workerResult'],parentObservation=audit['parentObservation'],workerTerminal=audit['workerTerminal'],commandTerminals=audit['commandTerminals'],phasePassed=False,adapterAccepted=False,metadataDecoded=False,coreDataAuditPassed=True,actualWorkerExitCode=1,prunerExitCode=0,nodeCoreValidationExitCode=0,metadataExitCode=1,allMonitoredGroupsGone=True,finalProtectionError=None,retainedOriginalCopiesVerified=35,sourceProtectedRowsVerified=24359,fixedFamiliesVerified=9,coreTypes=35,originalFunctionsCompared=93,convertedUnreachableStubs=14,retainedFunctionImports=49,retainedClockImports=6,retainedPollImports=2,toolingMetadataParserWasmExecutedInOriginalPhase=True,normalizationCallCountSourceCoupled=1,prunerCallsObserved=1,rootToolObservation=audit['rootToolObservationOnly'],dataAudit=row(HERE/'data-audit.json'),independentCoreAudit=row(HERE/'core-analysis.json'),readerHistory=row(HERE/'reader-history.json'),ownerActionsInvoked=False,normalizerPrunerValidatorOrMetadataToolRerun=False,applicationEngineOrGuestExecuted=False,adapterPromoted=False,operationalAdmission=False,runtimeAcceptanceClaim=False,newRootAuthority=None)
put('results.json',result)
fixed={k:result[k]for k in ['schemaVersion','state','verifiedPassed','sourceIndexSha256','phasePassed','adapterAccepted','metadataDecoded','coreDataAuditPassed','actualWorkerExitCode','prunerExitCode','nodeCoreValidationExitCode','metadataExitCode','allMonitoredGroupsGone','ownerActionsInvoked','operationalAdmission','runtimeAcceptanceClaim']}
exact={k:result[k]for k in ['rootObservation','normalizedAdapter','prunedAdapter','metadataPayload','coreValidation','structuralAudit','metadataTerminal','workerTerminal','workerResult','parentObservation']}
put('result-contract.json',dict(schemaVersion=1,requiredFixedValues=fixed,requiredExactDescriptors=exact,results=row(HERE/'results.json'),grantsPhaseOrRetryAuthority=False,fullPhaseAcceptance=False))
put('required-correction-contract.json',dict(schemaVersion=1,state='PROSPECTIVE_CLOCK_METADATA_ONLY_SOURCE_CORRECTION_CONTRACT_V1',preserveFailedRootObservation=result['rootObservation'],preserveFailedWorkerResult=result['workerResult'],preserveFailedParentObservation=result['parentObservation'],exactPayload=result['metadataPayload'],preserveNormalized=result['normalizedAdapter'],preservePruned=result['prunedAdapter'],requirements=['Authenticate exact existing package-aware decoder/tool source, binary and complete loader closure before import/invocation','New explicit Root metadata-only authority and fresh private output; retain raw terminal and whole output before assertions','Decode the complete retained WIT-package payload and validate/elaborate required aliases/dependencies; a component header or substring is insufficient','No repeated normalization, pruning, core validation, native build, component, engine, guest or clock operation','Keep the original phase failed/unaccepted and provenance contexts exact; do not project a new result into old states','Any later overall private artifact acceptance needs explicit composition/data review; no default adapter replacement or interface-policy widening'],suggestedNativeToolEvidence=str(S.parent/'foundation-zlib/cost-component-wit-parameter-parser-regression-root-v1/results.json'),nativeApiPrimarySource='https://github.com/bytecodealliance/wasm-tools/blob/v1.235.0/src/bin/wasm-tools/component.rs#L507-L528',actualNewSource=None,actualNewSourcePeer=None,newRootAuthority=None,newInvocation=None,newMetadataResult=None,grantsAnyActionAuthority=False))
put('review-receipt.json',dict(schemaVersion=1,state='CLOCK_ADAPTER_FAILED_PHASE_REVIEW_COMPLETE_V1',results=row(HERE/'results.json'),contract=row(HERE/'result-contract.json'),correctionContract=row(HERE/'required-correction-contract.json'),checks=audit['checks'],independentDataReview=True,ownerActionsInvoked=False,originalPhaseRemainsFailed=True))
for p in HERE.glob('*.py'):ast.parse(p.read_text())
files=[]
for p in sorted(HERE.rglob('*')):
    assert not p.is_symlink()
    if p.is_file():d=row(p);d['path']=p.relative_to(HERE).as_posix();files.append(d)
put('index.json',dict(schemaVersion=1,files=files))
for d in files:
    actual=row(HERE/d['path']);assert(actual['sha256'],actual['bytes'])==(d['sha256'],d['bytes'])
print(json.dumps(dict(index=row(HERE/'index.json'),results=row(HERE/'results.json'),contract=row(HERE/'result-contract.json'),correctionContract=row(HERE/'required-correction-contract.json'),members=len(files),checks=audit['checks'],originalPhaseRemainsFailed=True)))
